<style>.event-layout{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(280px,.7fr);gap:26px;align-items:start}.event-cover{overflow:hidden;margin-bottom:20px;border-radius:24px}.event-cover img{display:block;width:100%;max-height:520px;object-fit:cover}.event-block{margin-bottom:16px;padding:28px;border:1px solid var(--border);border-radius:24px;background:#fff}.event-block h2{margin-top:0}.event-block p,.event-program{color:var(--muted-foreground);line-height:1.75}.event-program{white-space:pre-line}.event-facts{position:sticky;top:105px;padding:26px;border-radius:24px;background:var(--gradient-cool)}.event-facts p{padding-bottom:13px;border-bottom:1px solid var(--border)}.event-alert{margin-bottom:16px;padding:14px 18px;border-radius:14px;background:#fee2e2;color:#991b1b;font-weight:700}.registration{margin-top:24px;padding:30px;border:1px solid var(--border);border-radius:24px;background:#fff}.registration h2{font-size:27px}.registration .btn{margin-top:18px}.closed{margin-top:24px;padding:18px 22px;border-radius:16px;background:var(--muted);font-weight:700}@media(max-width:820px){.event-layout{grid-template-columns:1fr}.event-facts{position:static}.event-block,.registration{padding:22px}}</style>
