<section class="content"><div class="wrap"><?php if((int)$event['cancelled']):?><div class="event-alert">Evento annullato</div><?php endif;?><div class="event-layout"><main><?php $cover=!empty($event['cover_image'])?(string)$event['cover_image']:($event['audience']==='cat'?'/idemaclima/public/brand-assets/campus-eventi-cat.webp.php':'/idemaclima/public/brand-assets/campus-eventi-aperti.webp.php'); ?><div class="event-cover"><img src="<?=e($cover)?>" alt="<?=e($event['title'])?>"></div><?php if(!empty($event['description'])):?><section class="event-block"><h2>L’evento</h2><p><?=nl2br(e($event['description']))?></p></section><?php endif;?><?php if(!empty($event['program'])):?><section class="event-block"><h2>Programma</h2><div class="event-program"><?=e($event['program'])?></div></section><?php endif;?></main><aside class="event-facts"><span class="section-label">— Informazioni</span><?php if(!empty($event['category'])):?><p><strong>Categoria</strong><br><?=e($event['category'])?></p><?php endif;?><p><strong>Data e ora</strong><br><?=e(date('d/m/Y · H:i',strtotime((string)$event['starts_at'])))?></p><?php if(!empty($event['ends_at'])):?><p><strong>Conclusione</strong><br><?=e(date('d/m/Y · H:i',strtotime((string)$event['ends_at'])))?></p><?php endif;?><?php if(!empty($event['speaker'])):?><p><strong>Relatore / referente</strong><br><?=e($event['speaker'])?></p><?php endif;?><?php if(!empty($event['location'])):?><p><strong>Luogo</strong><br><?=e($event['location'])?><?=!empty($event['address'])?'<br>'.e($event['address']):''?></p><?php endif;?><?php if(!empty($event['max_seats'])):?><p><strong>Disponibilità</strong><br><?=max(0,(int)$event['max_seats']-(int)$event['booked'])?> posti disponibili</p><?php endif;?><?php if($event['fee_amount']!==null && $event['fee_amount']!==''):?><p><strong>Quota di iscrizione</strong><br>€ <?=e(number_format((float)$event['fee_amount'],2,',','.'))?><?php if(!empty($event['fee_note'])):?><br><small><?=e($event['fee_note'])?></small><?php endif;?></p><?php endif;?></aside></div>
<?php $deadlineOk=empty($event['registration_deadline'])||strtotime((string)$event['registration_deadline'])>=time();$notStarted=strtotime((string)$event['starts_at'])>time();$full=!empty($event['max_seats'])&&(int)$event['booked']>=(int)$event['max_seats'];$open=(int)$event['registration_open']===1&&!(int)$event['cancelled']&&$deadlineOk&&$notStarted&&(!$full||(int)($event['waitlist_enabled']??1));?>
<?php if($open):?><div class="registration"><span class="section-label">— <?=$full?'Lista d’attesa':'Partecipa'?></span><h2><?=$full?'Iscriviti alla lista d’attesa':'Iscriviti all’evento'?></h2><form method="post" action="<?= $event['audience']==='cat'?'/idemaclima/campus/cat/':'/idemaclima/campus/' ?><?=e($event['slug'])?>/iscrizione"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><div class="hp" aria-hidden="true"><label>Sito web aziendale<input name="company_website" tabindex="-1" autocomplete="off"></label></div><div class="formgrid"><label>Nome<input name="first_name" maxlength="120" required value="<?=e($catUser['contact_first_name']??'')?>"></label><label>Cognome<input name="last_name" maxlength="120" required value="<?=e($catUser['contact_last_name']??'')?>"></label><label>Email<input type="email" maxlength="190" name="email" required value="<?=e($catUser['email']??'')?>"></label><label>Telefono<input name="phone" maxlength="50" value="<?=e($catUser['phone']??'')?>"></label><label>Azienda<input name="company" maxlength="190" value="<?=e($catUser['company_name']??'')?>"></label><label>Ruolo<input name="role" maxlength="120"></label><label class="full">Note<textarea name="notes" maxlength="4000"></textarea></label><label class="privacy-consent"><input type="checkbox" name="privacy" value="1" required><span>Ho letto l’<a href="https://www.iubenda.com/privacy-policy/38092343/full-legal" target="_blank" rel="noopener">informativa privacy</a> e acconsento al trattamento dei dati per la gestione della richiesta. *</span></label></div><button class="btn" type="submit"><?=$full?'Entra in lista d’attesa':'Invia iscrizione'?></button></form></div><?php else:?><div class="closed"><?=(int)$event['cancelled']?'Evento annullato.':'Iscrizioni chiuse.'?></div><?php endif;?></div></section>
